#!/bin/bash
# Uninstall script for GIMP
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling GIMP..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping GIMP if running..."
pkill -f "GIMP" 2>/dev/null || true

# Remove /Applications/GIMP.app
echo "Removing /Applications/GIMP.app..."
if [ -d "/Applications/GIMP.app" ]; then
    rm -rf "/Applications/GIMP.app" 2>/dev/null || true
elif [ -f "/Applications/GIMP.app" ]; then
    rm -f "/Applications/GIMP.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Gimp
echo "Removing $HOME/Library/Application Support/Gimp..."
if [ -d "$HOME/Library/Application Support/Gimp" ]; then
    rm -rf "$HOME/Library/Application Support/Gimp" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Gimp" ]; then
    rm -f "$HOME/Library/Application Support/Gimp" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/org.gimp.gimp-3.2.plist
echo "Removing $HOME/Library/Preferences/org.gimp.gimp-3.2.plist..."
if [ -d "$HOME/Library/Preferences/org.gimp.gimp-3.2.plist" ]; then
    rm -rf "$HOME/Library/Preferences/org.gimp.gimp-3.2.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/org.gimp.gimp-3.2.plist" ]; then
    rm -f "$HOME/Library/Preferences/org.gimp.gimp-3.2.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/org.gimp.gimp-3.2.savedState
echo "Removing $HOME/Library/Saved Application State/org.gimp.gimp-3.2.savedState..."
if [ -d "$HOME/Library/Saved Application State/org.gimp.gimp-3.2.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/org.gimp.gimp-3.2.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/org.gimp.gimp-3.2.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/org.gimp.gimp-3.2.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
